import numpy as np
import signal
import sys

def timeout_handler(signum, frame):
    raise TimeoutError("Test timed out - likely infinite loop")

# Set a timeout for each test
def run_with_timeout(func, timeout_seconds=5):
    """Run a function with a timeout"""
    signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(timeout_seconds)
    try:
        result = func()
        signal.alarm(0)  # Cancel alarm
        return result
    except TimeoutError as e:
        signal.alarm(0)  # Cancel alarm
        raise e

# Test 1: np.gcd(np.array([np.inf], dtype=np.object_), 33)
try:
    def test1():
        return np.gcd(np.array([np.inf], dtype=np.object_), 33)
    result = run_with_timeout(test1)
    probe("np.gcd(np.array([np.inf], dtype=np.object_), 33)", result)
except TimeoutError as e:
    probe("np.gcd(np.array([np.inf], dtype=np.object_), 33)", "__error__: TimeoutError: " + str(e))
except Exception as e:
    probe("np.gcd(np.array([np.inf], dtype=np.object_), 33)", "__error__: " + type(e).__name__ + ": " + str(e))

